from pathlib import Path
import zipfile,json,base64
R=Path(__file__).resolve().parents[2]
entries=[{'folder':'applewoods_skygrass_v1','scene':'entree_pommier','zip':'APPLEWOODS_SKYGRASS_calques.zip','title':'L’entrée du vieux pommier','tag':'01 / APPLE WOODS × SKY PEAK','details':'Herbe claire, chemin crème-ocre, vingt pommiers indépendants et entrée dans un gros tronc. Fleurs natives Sky Peak sur leurs propres calques.','spec':'552 × 408 · 30 calques · 4 phases florales','gallery':'apercu_applewoods_skygrass_v1.html'}, {'folder':'siphons_ecoulement_v3','scene':'siphons_ecoulement','zip':'SIPHONS_ECOULEMENT_V3_calques.zip','title':'Les courants des siphons','tag':'02 / EAU RÉGÉNÉRÉE','details':'Écoulement2D dirigé vers les siphons et autour des rochers. Palette bleu–turquoise, raccords de rive discrets et chaussée sèche conservée.','spec':'456 × 384 · 9 calques · 128 phases','gallery':'apercu_siphons_ecoulement_v3.html'}]
for e in entries:
 p=R/'renders'/e['folder']
 with zipfile.ZipFile(p/e['zip'],'w',zipfile.ZIP_DEFLATED) as z:
  for f in sorted(p.rglob('*')):
   if f.is_file() and f.suffix!='.zip' and 'bruts' not in f.parts:z.write(f,f.relative_to(p))
 e['animated']='data:image/webp;base64,'+base64.b64encode((p/e['scene']/'ANIMATION_COMPLETE.webp').read_bytes()).decode()
 e['still']='data:image/png;base64,'+base64.b64encode((p/e['scene']/'COMPOSITION.png').read_bytes()).decode()
html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Le vieux pommier et les siphons</title><style>*{box-sizing:border-box}body{margin:0;background:#10201d;color:#ecf0dc;font:16px system-ui}main{max-width:1250px;margin:44px auto;padding:0 24px}header{margin-bottom:32px}h1{font-size:36px;font-weight:600;letter-spacing:-1px;margin:10px 0}header p{color:#b5c9bd;max-width:760px;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#192e28;border:1px solid #3c5144;border-radius:14px;padding:22px}.card:nth-child(2){background:#182d38;border-color:#344d5a}.tag{font-size:12px;letter-spacing:2px;color:#b4d286}h2{font-size:24px;font-weight:550;margin:10px 0}.image{min-height:408px;display:flex;align-items:center;justify-content:center;background:#10201d;border-radius:8px;overflow:hidden;margin:20px 0}img{image-rendering:pixelated;max-width:100%;height:auto}.spec{color:#d0dcae;font-size:13px}.card p{color:#c0d0c7;line-height:1.6}button,a{font:14px system-ui;color:#edf1d6;background:#304637;border:1px solid #718469;border-radius:6px;padding:9px 13px;cursor:pointer;text-decoration:none;display:inline-block;margin:8px 8px 0 0}.file{font-size:12px;color:#9eb7a7;overflow-wrap:anywhere;margin-top:16px}footer{color:#9bb3a6;font-size:13px;line-height:1.6;margin-top:28px}@media(max-width:900px){.grid{grid-template-columns:1fr}h1{font-size:29px}.image{min-height:0}}</style><main><header><div class="tag">DEUX ZONES / PNG · CALQUES · ANIMATIONS</div><h1>Le vieux pommier et les siphons</h1><p>La forêt a été réalisée en premier, puis la reprise de l’eau. Les deux scènes sont animées ci-dessous ; chaque pack contient ses calques transparents, ses frames et son fichier OpenRaster.</p></header><div class="grid" id="grid"></div><footer>Recomposition des calques contrôlée. Les fleurs conservent leurs phases natives ; le courant est une approximation stationnaire2D avec obstacles, pas une simulation3D complète. Pas de test runtime PMDO/GPU ou de collisions configurées.</footer></main><script>const entries='''+json.dumps(entries,ensure_ascii=False)+''';for(const e of entries){const card=document.createElement('section');card.className='card';const tag=document.createElement('div');tag.className='tag';tag.textContent=e.tag;const title=document.createElement('h2');title.textContent=e.title;const spec=document.createElement('div');spec.className='spec';spec.textContent=e.spec;const wrap=document.createElement('div');wrap.className='image';const im=new Image();im.src=e.animated;im.alt=e.title;wrap.append(im);const text=document.createElement('p');text.textContent=e.details;const button=document.createElement('button');button.textContent='Pause';button.onclick=()=>{const running=button.textContent==='Pause';im.src=running?e.still:e.animated;button.textContent=running?'Reprendre':'Pause'};const link=document.createElement('a');link.textContent='Fichiers et calques';link.target='_blank';link.rel='noopener';link.href='https://github.com/meromoonmeri/guilde-treehouse-pmd/tree/arena/01a095e8-guilde-treehouse-pmd/renders/'+e.folder;const note=document.createElement('div');note.className='file';note.textContent='Galerie détaillée : '+e.gallery+' — Pack : '+e.zip;card.append(tag,title,spec,wrap,text,button,link,note);grid.append(card)}</script>'''
(R/'apercu_pommier_et_siphons.html').write_text(html)
print('Two ZIP packs and the combined animated viewer written.')
